/*
 * Web Push handlers (docs/api-contract.md section 15). Loaded into the Workbox service worker
 * (/sw.js, generated by vite-plugin-pwa) through `workbox.importScripts` in vite.config.ts, so the
 * app has one service worker. No skipWaiting here: new versions wait for the Reload banner.
 * In `npm run dev` there is no generated /sw.js, so this file is registered on its own.
 *
 * Push payload from the API: { title, body, url, tag }. The text is generic on purpose (lock screens):
 * no names, no content.
 */

self.addEventListener('push', (event) => {
  let msg = {};
  try { msg = event.data ? event.data.json() : {}; } catch { /* not JSON: show the default */ }
  const url = typeof msg.url === 'string' && msg.url.startsWith('/') ? msg.url : '/notifications';
  event.waitUntil((async () => {
    await self.registration.showNotification(msg.title || 'New notification', {
      body: msg.body || '',
      icon: '/icon.svg',
      badge: '/icon.svg',
      tag: msg.tag || 'general',      // one per kind on the device: a burst replaces, not stacks
      renotify: true,
      requireInteraction: msg.tag === 'urgent',
      data: { url },
    });
    // Open tabs refresh their unread count.
    const tabs = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    tabs.forEach((c) => c.postMessage({ type: 'push' }));
  })());
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const url = new URL(event.notification.data?.url || '/notifications', self.location.origin).href;
  event.waitUntil((async () => {
    const tabs = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    const tab = tabs.find((c) => new URL(c.url).origin === self.location.origin);
    if (tab) { await tab.focus(); return tab.navigate(url).catch(() => self.clients.openWindow(url)); }
    return self.clients.openWindow(url);
  })());
});
